/**
 * The committed record of a locally run AI tournament. Generated by
 * `pnpm --filter @boardgames/core tournament <slug>` into the game's web folder
 * and rendered read-only on the game's Tournament page. Two kinds:
 *   - head-to-head — for each table size, every pair of strategies and how
 *     often each came out ahead (files without a `kind` are this one);
 *   - benchmark — for co-op games: each strategy playing every seat, and how
 *     often the table won.
 */

import { z } from "zod";

export const TOURNAMENT_RESULTS_FORMAT = 1;

const MatchupSchema = z
  .object({
    /** Strategy ids; `a` sat in the even seats of even-numbered games. */
    a: z.string().min(1),
    b: z.string().min(1),
    games: z.number().int().min(1),
    aWins: z.number().int().min(0),
    bWins: z.number().int().min(0),
    draws: z.number().int().min(0),
    /** Mean final score of the side's seats per game; `null` when the game keeps no score. */
    avgScoreA: z.number().nullable(),
    avgScoreB: z.number().nullable(),
  })
  .refine((m) => m.aWins + m.bWins + m.draws === m.games, {
    message: "aWins + bWins + draws must equal games",
  })
  .refine((m) => m.a !== m.b, { message: "a matchup needs two different strategies" });
export type TournamentMatchup = z.infer<typeof MatchupSchema>;

const TableSchema = z.object({
  playerCount: z.number().int().min(2),
  matchups: z.array(MatchupSchema),
});
export type TournamentTable = z.infer<typeof TableSchema>;

const StrategyLabelSchema = z.object({ id: z.string().min(1), label: z.string().min(1) });

const HeadToHeadResultsSchema = z.object({
  formatVersion: z.literal(TOURNAMENT_RESULTS_FORMAT),
  /** Absent in files written before benchmarks existed. */
  kind: z.literal("head-to-head").optional(),
  slug: z.string().min(1),
  /** ISO timestamp of the latest run merged into this file. */
  generatedAt: z.string().min(1),
  /** Label snapshot at generation time, in the manifest's order. */
  strategies: z.array(StrategyLabelSchema).min(2),
  tables: z.array(TableSchema).min(1),
});
export type HeadToHeadResults = z.infer<typeof HeadToHeadResultsSchema>;

const BenchmarkRunSchema = z
  .object({
    /** The strategy that played every seat. */
    strategy: z.string().min(1),
    games: z.number().int().min(1),
    /** Games the table won. */
    wins: z.number().int().min(0),
    /** Mean table score per game; `null` when the game keeps no score. */
    avgScore: z.number().nullable(),
  })
  .refine((r) => r.wins <= r.games, { message: "wins cannot exceed games" });
export type BenchmarkRun = z.infer<typeof BenchmarkRunSchema>;

const BenchmarkTableSchema = z.object({
  playerCount: z.number().int().min(1),
  runs: z.array(BenchmarkRunSchema),
});
export type BenchmarkTable = z.infer<typeof BenchmarkTableSchema>;

const BenchmarkResultsSchema = z.object({
  formatVersion: z.literal(TOURNAMENT_RESULTS_FORMAT),
  kind: z.literal("benchmark"),
  slug: z.string().min(1),
  generatedAt: z.string().min(1),
  strategies: z.array(StrategyLabelSchema).min(1),
  tables: z.array(BenchmarkTableSchema).min(1),
});
export type BenchmarkResults = z.infer<typeof BenchmarkResultsSchema>;

export const TournamentResultsSchema = z.union([BenchmarkResultsSchema, HeadToHeadResultsSchema]);
export type TournamentResults = z.infer<typeof TournamentResultsSchema>;

export function isBenchmark(results: TournamentResults): results is BenchmarkResults {
  return results.kind === "benchmark";
}

/** Outcome tallies for one matchup, before they are frozen into the file. */
export interface MatchupTally {
  games: number;
  aWins: number;
  bWins: number;
  draws: number;
  scoreA: number;
  scoreB: number;
  scored: number;
}

export function emptyTally(): MatchupTally {
  return { games: 0, aWins: 0, bWins: 0, draws: 0, scoreA: 0, scoreB: 0, scored: 0 };
}

export function tallyToMatchup(a: string, b: string, t: MatchupTally): TournamentMatchup {
  const round1 = (n: number) => Math.round(n * 10) / 10;
  return {
    a,
    b,
    games: t.games,
    aWins: t.aWins,
    bWins: t.bWins,
    draws: t.draws,
    avgScoreA: t.scored > 0 ? round1(t.scoreA / t.scored) : null,
    avgScoreB: t.scored > 0 ? round1(t.scoreB / t.scored) : null,
  };
}

/** Win and score tallies for one strategy's benchmark runs. */
export interface BenchmarkTally {
  games: number;
  wins: number;
  score: number;
  scored: number;
}

export function emptyBenchmarkTally(): BenchmarkTally {
  return { games: 0, wins: 0, score: 0, scored: 0 };
}

export function tallyToRun(strategy: string, t: BenchmarkTally): BenchmarkRun {
  return {
    strategy,
    games: t.games,
    wins: t.wins,
    avgScore: t.scored > 0 ? Math.round((t.score / t.scored) * 10) / 10 : null,
  };
}

/**
 * Fold a fresh run into an earlier file: matchups (or benchmark runs) the run
 * played replace the old ones (matchups in either orientation); everything
 * else is kept, so a heavy game can be run one table size or one strategy at a
 * time — except entries of a strategy the game no longer offers
 * (`fresh.strategies` is the manifest's). A file of the other kind is replaced.
 */
export function mergeResults(
  previous: TournamentResults | null,
  fresh: TournamentResults,
): TournamentResults {
  if (isBenchmark(fresh)) {
    return previous && isBenchmark(previous) ? mergeBenchmarks(previous, fresh) : fresh;
  }
  if (!previous || isBenchmark(previous)) return fresh;
  const key = (n: number, a: string, b: string) => `${n}:${[a, b].sort().join("|")}`;
  const played = new Set(
    fresh.tables.flatMap((t) => t.matchups.map((m) => key(t.playerCount, m.a, m.b))),
  );
  const offered = new Set(fresh.strategies.map((s) => s.id));
  const sizes = new Set([...previous.tables, ...fresh.tables].map((t) => t.playerCount));
  const tables = [...sizes]
    .sort((x, y) => x - y)
    .map((playerCount) => {
      const kept = (
        previous.tables.find((t) => t.playerCount === playerCount)?.matchups ?? []
      ).filter(
        (m) => offered.has(m.a) && offered.has(m.b) && !played.has(key(playerCount, m.a, m.b)),
      );
      const added = fresh.tables.find((t) => t.playerCount === playerCount)?.matchups ?? [];
      return { playerCount, matchups: [...kept, ...added] };
    });
  return { ...fresh, tables };
}

function mergeBenchmarks(previous: BenchmarkResults, fresh: BenchmarkResults): BenchmarkResults {
  const key = (n: number, strategy: string) => `${n}:${strategy}`;
  const played = new Set(
    fresh.tables.flatMap((t) => t.runs.map((r) => key(t.playerCount, r.strategy))),
  );
  const offered = new Set(fresh.strategies.map((s) => s.id));
  const sizes = new Set([...previous.tables, ...fresh.tables].map((t) => t.playerCount));
  const tables = [...sizes]
    .sort((x, y) => x - y)
    .map((playerCount) => {
      const kept = (previous.tables.find((t) => t.playerCount === playerCount)?.runs ?? []).filter(
        (r) => offered.has(r.strategy) && !played.has(key(playerCount, r.strategy)),
      );
      const added = fresh.tables.find((t) => t.playerCount === playerCount)?.runs ?? [];
      // Manifest order, so a partial rerun doesn't shuffle the rows.
      const order = fresh.strategies.map((s) => s.id);
      const runs = [...kept, ...added].sort(
        (x, y) => order.indexOf(x.strategy) - order.indexOf(y.strategy),
      );
      return { playerCount, runs };
    });
  return { ...fresh, tables };
}

/** Win rate of `row` against `col` at one table, and the average score gap; `null` if unplayed. */
export function headToHead(
  table: TournamentTable,
  row: string,
  col: string,
): { winRate: number; scoreDiff: number | null; games: number } | null {
  for (const m of table.matchups) {
    const forward = m.a === row && m.b === col;
    if (!forward && !(m.a === col && m.b === row)) continue;
    const wins = (forward ? m.aWins : m.bWins) + m.draws / 2;
    const mine = forward ? m.avgScoreA : m.avgScoreB;
    const theirs = forward ? m.avgScoreB : m.avgScoreA;
    return {
      winRate: wins / m.games,
      scoreDiff: mine === null || theirs === null ? null : Math.round((mine - theirs) * 10) / 10,
      games: m.games,
    };
  }
  return null;
}
